INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (443, 1, '-b 범위', '`mke2fs -b` 에서 **허용되는 블록 크기** 는 무엇일까요?', '2 의 거듭제곱이에요.', NULL, NULL, '[]', 'choice', '["512 이상 4096 이하의 임의 값", "4096 바이트로 고정", "1024~65536 의 2 의 거듭제곱", "1024 이상 1MB 이하의 임의 값"]', 2, 'mke2fs 문서는 block-size 가 1024 에서 65536 까지의 2 의 거듭제곱이라고 설명하며 일반적으로 기본 블록 크기는 4k 라고 합니다.', NULL, NULL, NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 2, '-m 기본값', '`mke2fs -m` 의 **기본 퍼센트** 는 얼마일까요?', '슈퍼유저용 예약이에요.', NULL, NULL, '[]', 'choice', '["1%", "5%", "10%", "0%"]', 1, '문서는 -m 이 슈퍼유저용으로 예약할 블록 비율을 정하며 기본값이 5% 라고 설명합니다.', NULL, NULL, NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 3, '-i 옵션', '`mke2fs -i` 는 무엇을 정할까요?', 'inode 비율이에요.', NULL, NULL, '[]', 'choice', '["inode 당 바이트 비율", "inode 하나의 크기", "예약할 블록의 비율", "저널 영역의 크기"]', 0, '문서는 -i 가 바이트/inode 비율을 정하며 mke2fs 가 bytes-per-inode 바이트마다 inode 하나를 만든다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 4, '-N 옵션', '`mke2fs -N` 은 무엇을 할까요?', '개수를 직접 정해요.', NULL, NULL, '[]', 'choice', '["블록 크기의 기본 계산을 덮어쓴다", "볼륨 레이블을 덮어쓴다", "저널 크기를 정한다", "inode 수의 기본 계산을 덮어쓴다"]', 3, '문서는 -N 이 파일시스템에 예약할 inode 수의 기본 계산을 덮어쓴다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 5, '-L 길이', '볼륨 레이블(`-L`)의 **최대 길이** 는 얼마일까요?', '바이트 단위예요.', NULL, NULL, '[]', 'choice', '["8바이트", "32바이트", "16바이트", "255바이트"]', 2, '문서는 -L 이 볼륨 레이블을 정하며 최대 길이가 16바이트라고 설명합니다.', NULL, NULL, NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 6, '-n 옵션', '`mke2fs -n` 은 무엇을 할까요?', '시험이에요.', NULL, NULL, '[]', 'choice', '["배드 블록만 검사한다", "만들지 않고 보여 준다", "저널 없이 만든다", "기존 파일시스템을 지운다"]', 1, '문서는 -n 이 파일시스템을 실제로 만들지 않고 만들 내용을 보여 준다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 7, '-F 옵션', '`mke2fs -F` 는 무엇을 할까요?', '강제예요.', NULL, NULL, '[]', 'choice', '["장치가 파티션이 아니어도 강제로 만든다", "이미 마운트된 장치를 자동으로 해제한다", "배드 블록을 강제로 복구한다", "저널을 강제로 끈다"]', 0, '문서는 -F 가 지정한 장치가 파티션이 아니어도 파일시스템을 강제로 만든다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 8, '-d 옵션', '`mke2fs -d` 는 무엇을 할까요?', '넣는 옵션이에요.', NULL, NULL, '[]', 'choice', '["디렉터리를 마운트 지점으로 정한다", "디렉터리의 권한을 초기화한다", "디렉터리를 검사한다", "디렉터리 내용을 루트에 복사한다"]', 3, '문서는 -d 가 주어진 디렉터리나 tarball 의 내용을 파일시스템의 루트 디렉터리에 복사한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 9, 'mkfs.ext4', '`mke2fs` 를 `mkfs.ext4` 라는 이름으로 실행하면 어떻게 될까요?', '옵션이 암시돼요.', NULL, NULL, '[]', 'choice', '["-j 옵션이 함께 암시된다", "-F 옵션이 함께 암시된다", "-t ext4 가 암시된다", "-n 옵션이 함께 암시된다"]', 2, '문서는 mke2fs 를 mkfs.ext2·ext3·ext4 같은 이름으로 실행하면 -t XXX 가 암시된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 10, '파일시스템 유형', '만들 **파일시스템 유형** 을 정하는 옵션입니다. 빈칸을 채우세요.', 'type 의 t 예요.', NULL, NULL, '[]', 'fill', '["-t", "-T", "-b", "-j"]', NULL, '-t 는 파일시스템 유형(ext2·ext3·ext4 등)을 정합니다. 대문자 -T 는 사용 용도입니다.', '[0]', 'mke2fs {0} ext4 /dev/sdb1', NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 11, '시험 실행', '실제로 만들지 않고 **할 일만 보여 주는** 옵션입니다. 빈칸을 채우세요.', 'dry run 입니다.', NULL, NULL, '[]', 'fill', '["-n", "-F", "-c", "-j"]', NULL, '-n 은 만들지 않고 할 일을 보여 줍니다. -F 는 강제로 만듭니다.', '[0]', 'mke2fs {0} /dev/sdb1', NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]'),
  (443, 12, '파일시스템 만들기', '파일시스템을 시험하고 만드는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '시험 → 생성 → 복사예요.', NULL, NULL, '[]', 'order', '["`mke2fs -n` 으로 만들 내용을 미리 본다", "`-t ext4`, `-L` 같은 옵션을 주어 실제로 만든다", "필요하면 `-d` 로 디렉터리 내용을 함께 복사해 넣는다"]', NULL, '문서의 -n·-t·-L·-d 설명을 이은 일반 절차입니다.', '[0, 1, 2]', NULL, NULL, '[{"title": "mke2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/mke2fs.8.html"}]');
